const business_licenses_metadata = {"name": "Business Licenses - Current Active", "description": "This dataset contains all current and active business licenses issued by the Department of Business Affairs and Consumer Protection.  This dataset contains a large number of records /rows of data and may not be viewed in full in Microsoft Excel.  Therefore, when downloading the file, select CSV from the Export menu.  Open the file in an ASCII text editor, such as Notepad or Wordpad, to view and search.  \r\n\r\n \r\nData fields requiring description are detailed below. \r\n\r\nAPPLICATION TYPE:  'ISSUE' is the record associated with the initial license application.  'RENEW' is a subsequent renewal record.  All renewal records are created with a term start date and term expiration date.  'C_LOC' is a change of location record.  It means the business moved.   'C_CAPA' is a change of capacity record.  Only a few license types my file this type of application.  'C_EXPA' only applies to businesses that have liquor licenses.  It means the business location expanded.\r\n\r\nLICENSE STATUS: 'AAI' means the license was issued. \r\n\r\nBusiness license owners may be accessed at:  http://data.cityofchicago.org/Community-Economic-Development/Business-Owners/ezma-pppn\r\nTo identify the owner of a business, you will need the account number or legal name.\r\n\r\n \r\nData Owner: Business Affairs and Consumer Protection \r\n \r\nTime Period: Current \r\n \r\nFrequency: Data is updated daily", "dataUri": "https://data.cityofchicago.org/resource/uupf-x98q", "attribution": "City of Chicago", "attributionLink": "http://www.cityofchicago.org", "actualDatasourceUri": null, "createdAt": "15 Dec 2011", "dataUpdatedAt": "27 Jun 2024", "metadataUpdatedAt": "27 Jun 2024", "accessedOn": "27 Jun 2024", "dataUseNotes": "Only information about the most recent licenses for businesses with valid coordinates in Ward 20 has been included on the map."};